import java.lang.reflect.Constructor;
import java.util.HashMap;
import java.util.Map;

public class MiniDi {

    static class MiniContainer {
        private final Map<Class<?>, Object> singletons = new HashMap<>();

        @SuppressWarnings("unchecked")
        <T> T get(Class<T> type) {
            Object existing = singletons.get(type);
            if (existing != null) {
                return (T) existing;
            }
            try {
                Constructor<?> ctor = type.getDeclaredConstructors()[0];
                Class<?>[] paramTypes = ctor.getParameterTypes();
                Object[] args = new Object[paramTypes.length];
                for (int i = 0; i < paramTypes.length; i++) {
                    args[i] = get(paramTypes[i]);
                }
                Object created = ctor.newInstance(args);
                singletons.put(type, created);
                return (T) created;
            } catch (ReflectiveOperationException e) {
                throw new IllegalStateException("Cannot create " + type.getSimpleName(), e);
            }
        }
    }

    static class BookRepository {
        String findTitle(int id) { return "Book#" + id; }
    }
    static class BookService {
        private final BookRepository repository;
        BookService(BookRepository repository) { this.repository = repository; }
        String describe(int id) { return "Service says: " + repository.findTitle(id); }
    }

    static class BookController {
        private final BookService service;
        BookController(BookService service) { this.service = service; }
        String handle(int id) { return service.describe(id); }
    }

    public static void main(String[] args) {
        MiniContainer container = new MiniContainer();
        BookController controller = container.get(BookController.class);
        System.out.println(controller.handle(7));
        System.out.println(container.get(BookService.class) == container.get(BookService.class));
    }
}

