import jakarta.annotation.PostConstruct;
import jakarta.annotation.PreDestroy;
import org.springframework.stereotype.Component;

@Component
public class CacheWarmer {

    private final BookRepository books;

    public CacheWarmer(BookRepository books) {
        this.books = books;
        // do NOT use fields of injected beans for heavy work here; keep constructors light
    }

    @PostConstruct              // runs once, after the dependencies are injected
    void warm() {
        System.out.println("Warming cache with " + books.count() + " books");
    }

    @PreDestroy                 // runs once on graceful shutdown
    void close() {
        System.out.println("Releasing resources");
    }
}

