import org.springframework.boot.context.properties.ConfigurationProperties;

@ConfigurationProperties(prefix = "hello")
public record HelloProperties(String greeting) {
    public HelloProperties {
        if (greeting == null) greeting = "Hello";
    }
}

import org.springframework.boot.autoconfigure.AutoConfiguration;
import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;

@AutoConfiguration
@EnableConfigurationProperties(HelloProperties.class)
@ConditionalOnProperty(prefix = "hello", name = "enabled", matchIfMissing = true)
public class HelloAutoConfiguration {

    @Bean
    @ConditionalOnMissingBean            // the app can define its own Greeter and win
    public Greeter greeter(HelloProperties props) {
        return new Greeter(props.greeting());
    }
}

public class Greeter {
    private final String greeting;
    public Greeter(String greeting) { this.greeting = greeting; }
    public String greet(String name) { return greeting + ", " + name; }
}
